root=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review')
assert os.getuid()==1000 and not root.is_symlink() and root.is_dir()
assert shutil.disk_usage(root).free>=500*1024**2
sys.path.insert(0,str(root/'tools'))
from stage5_board_readonly_inventory import fingerprint
before=fingerprint()
report=root/'reports/stage5_02_board/final_acceptance'
assert not report.exists() and not report.is_symlink()
report.mkdir()
for row in ROWS:
 relative=PurePosixPath(row['file']);assert not relative.is_absolute() and '..' not in relative.parts
 target=report/str(relative);assert target.resolve().is_relative_to(report)
 data=base64.b64decode(row['data']);assert len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256']
 target.parent.mkdir(parents=True,exist_ok=True)
 with target.open('xb') as output:output.write(data)
 assert hashlib.sha256(target.read_bytes()).hexdigest()==row['sha256']
manifest=[{k:v for k,v in r.items() if k!='data'} for r in ROWS]
(report/'delivery_manifest.json').write_text(json.dumps(manifest,indent=2))
summary={'files':len(ROWS),'bytes':sum(r['bytes'] for r in ROWS),'all_hashes_verified':True,'original_321_unchanged':before==fingerprint(),'disk_free_bytes':shutil.disk_usage(root).free,'destination':str(report)}
assert summary['original_321_unchanged'] and summary['disk_free_bytes']>=500*1024**2
(report/'delivery_receipt.json').write_text(json.dumps(summary,indent=2))
print('DELIVERY_RECEIPT',json.dumps(summary),flush=True)
